# ── GENERATED by matsci-knowledge-base build/build_plugin.py — DO NOT EDIT (真源见 plugin.yaml) ──
# -*- coding: utf-8 -*-
"""caj_to_pdf — 把知网的 CAJ / KDH 文件转成可提取文字的 PDF。

为什么需要它
------------
知网（CNKI）的学位论文与部分期刊只提供自家专有的 `.caj`。而本库的提取链是
**PDF 闸门**（`lit_manual_import.py` 只认真 PDF 的魔数与页结构），CAJ 直接落进
`raw/pdf/` 只会变成永远提不出文字的垃圾文件。所以：

    下载 CAJ → 本工具转 PDF → 真 PDF 才进 raw/pdf/（收编/提取链）
                          ↘ 转换失败 → 原 CAJ 留在 _scratch，台账记 blocked_format

为什么不是"CAJViewer 打印 PDF"
------------------------------
CAJViewer 打印出来的 PDF 是**整页图片**：没有文字层，`lit_extract` 提不出正文，
大纲也丢——对以文字证据为生的知识库等于白存。caj2pdf 直接重建 PDF 对象，
保留文字与大纲（来源：caj2pdf README「使用 CAJViewer 的打印功能……得到的 PDF
文件的内容为图片，无法进行文字的选择，且原文献的大纲列表也会丢失」）。

依赖与来源（都不进 git）
------------------------
· 第三方转换器 `caj2pdf`（https://github.com/caj2pdf/caj2pdf，GLWTPL 许可）
  解在 `_scratch/caj2pdf/`（`_scratch/` 在 .gitignore 内）。位置解析顺序：
  环境变量 `CAJ2PDF_HOME` → `lit_config.yaml` 的 `cnki.caj2pdf_home` → 默认值。
· Python 侧：`PyPDF2`、`pdfrw`、`imagesize`、`Pillow`、`python-dateutil`。
· `mutool`：上游用它做最后一步 xref 修复。**本机没有 mutool**，因此
  `check_output` 被替换为 PyMuPDF（`fitz`）的等价实现——见 `_mutool_clean`。

能力边界（务必如实转述给用户）
------------------------------
· caj2pdf 官方口径是"佛系转换，成功与否皆是玄学"：只保证部分 CAJ，
  `HN` 格式（很多学位论文）**不支持**；遇到未知类型直接 `Unknown file type.`。
· 因此转换失败不是本工具的 bug，是上游能力边界。失败时保留原 CAJ 并记原因。
· 转换器会在**当前工作目录**写 `pdf.tmp` / `pdf_toc.pdf` 等临时文件，
  并在 import 期以 `./lib/bin/*.dll` 相对路径加载解码 DLL——
  所以 import 阶段固定在转换器目录里，convert 阶段再切到独立临时目录。

典型用法
--------
  python tools/caj_to_pdf.py --selftest
  python tools/caj_to_pdf.py --available
  python tools/caj_to_pdf.py "downloads/某论文.caj" -o "out/某论文.pdf"
  python tools/caj_to_pdf.py --batch "_scratch/lit-cnki-fetch/caj" --json

退出码
------
  0  全部成功（或目录里本来就没有 CAJ）；--selftest 全过
  3  批量**部分**成功——按逐篇 reason 重试即可，环境是好的；
     --selftest 专用码：失败子项全部为可选环境判据（caj2pdf/依赖未装齐），
     无环境无关失败——kb_toolcheck 据此精确豁免（SKIP）
  4  单篇/整批**全部**失败——大概率是格式不支持（HN 学位论文等）
  2  环境或用法问题：转换器未就绪（--available 不 ready）、缺参数；
     --selftest 存在环境无关失败（数据安全回归等）或装齐环境仍失败
"""

from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
import sys
import tempfile
from typing import Any, Optional

HERE = os.path.dirname(os.path.abspath(__file__))
VAULT = os.path.dirname(HERE)
if HERE not in sys.path:
    sys.path.insert(0, HERE)

try:  # 控制台统一 UTF-8，避免 GBK 下中文题名直接 UnicodeEncodeError
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    sys.stderr.reconfigure(encoding="utf-8", errors="replace")
except Exception:  # noqa: BLE001
    pass

DEFAULT_HOME_REL = "_scratch/caj2pdf"


# ---------------------------------------------------------------------------
# 位置解析 / 体检
# ---------------------------------------------------------------------------
def config_home() -> str:
    """lit_config.yaml 的 `cnki.caj2pdf_home`（相对库根或绝对路径）。"""
    try:
        import kb_lib as K
        cfg = K.load_lit_config() or {}
        v = ((cfg.get("cnki") or {}).get("caj2pdf_home") or "").strip()
    except Exception:  # noqa: BLE001
        v = ""
    if not v:
        return ""
    return v if os.path.isabs(v) else os.path.join(VAULT, v)


def resolve_home() -> str:
    """转换器目录：env → 配置 → 库内默认。返回绝对路径（不一定存在）。"""
    env = (os.environ.get("CAJ2PDF_HOME") or "").strip()
    for cand in (env, config_home(), os.path.join(VAULT, DEFAULT_HOME_REL)):
        if cand and os.path.isfile(os.path.join(cand, "cajparser.py")):
            return cand
    return os.path.join(VAULT, DEFAULT_HOME_REL)


def missing_python_deps() -> list[str]:
    import importlib.util as u
    return [m for m in ("PyPDF2", "pdfrw", "imagesize", "PIL", "dateutil")
            if not u.find_spec(m)]


def available() -> dict[str, Any]:
    """体检：到底能不能转。缺什么就写清楚缺什么，绝不"看起来能转"。"""
    home = resolve_home()
    av: dict[str, Any] = {
        "home": home,
        "home_ok": os.path.isfile(os.path.join(home, "cajparser.py")),
        "missing_python": missing_python_deps(),
        "fitz": False,
        "real_mutool": bool(shutil.which("mutool")),
        "ready": False,
        "reason": "",
    }
    try:
        import fitz  # noqa: F401
        av["fitz"] = True
    except Exception:  # noqa: BLE001
        av["reason"] = "缺 PyMuPDF（fitz）：最后一步 xref 修复无处可跑"
    if not av["home_ok"]:
        av["reason"] = (f"未找到 caj2pdf：{home}"
                        "（克隆到该目录，或用 cnki.caj2pdf_home / CAJ2PDF_HOME 指过去）")
    elif av["missing_python"]:
        av["reason"] = "缺 Python 依赖：" + ", ".join(av["missing_python"])
    elif not (av["fitz"] or av["real_mutool"]):
        av["reason"] = "既没有 PyMuPDF 也没有 mutool"
    else:
        av["ready"] = True
    return av


# ---------------------------------------------------------------------------
# mutool 的替身
# ---------------------------------------------------------------------------
def _mutool_clean(src: str, dst: str) -> str:
    """`mutool clean src dst` 的等价实现，返回实际用的引擎名。

    上游只在这一处用 mutool（修复 xref 表）。本机没装 MuPDF，而库里本来就有
    PyMuPDF（`lit_extract` 也靠它），所以用 `save(garbage=3, deflate=True)`
    做等价的"重排 + 清理 + 压缩"。将来若装了真 mutool，优先用真的。
    """
    real = shutil.which("mutool")
    if real:
        subprocess.run([real, "clean", src, dst], check=True, capture_output=True)
        return "mutool"
    import fitz
    doc = fitz.open(src)
    try:
        doc.save(dst, garbage=3, deflate=True)
    finally:
        doc.close()
    return "fitz"


class ShimError(Exception):
    """caj2pdf 发起了预期外的外部调用。"""


def install_clean_shim(cajparser_mod: Any) -> str:
    """把 `cajparser.check_output` 换成 `_mutool_clean`。

    `cajparser` 用的是 `from subprocess import check_output`，所以补丁点在它
    自己的模块命名空间——**不改第三方源码**，克隆目录保持与上游逐字节一致，
    将来换版本不必重新打补丁。
    """
    def shim(cmd, *a, **kw):  # noqa: ANN001
        if isinstance(cmd, (list, tuple)) and len(cmd) >= 4 and \
                str(cmd[0]).lower().startswith("mutool") and cmd[1] == "clean":
            return _mutool_clean(str(cmd[2]), str(cmd[3])).encode()
        raise ShimError(f"caj2pdf 发起了预期外的外部调用：{cmd!r}")

    cajparser_mod.check_output = shim
    return "patched"


# ---------------------------------------------------------------------------
# 转换
# ---------------------------------------------------------------------------
def convert_one(caj: str, pdf: str) -> dict[str, Any]:
    """转换单个文件。**永不抛异常**：结果一律进 dict（ok / reason / engine / pages）。

    上游会在 CWD 写 pdf.tmp / pdf_toc.pdf，也用 `SystemExit` 报"不支持"，
    所以 import 在转换器目录、convert 在临时目录，SystemExit 与其余异常全兜。
    """
    res: dict[str, Any] = {"ok": False, "caj": caj, "pdf": pdf, "engine": "",
                           "caj_format": "", "pages": 0, "bytes": 0,
                           "has_text_layer": False, "reason": ""}
    home = resolve_home()
    if not os.path.isfile(os.path.join(home, "cajparser.py")):
        res["reason"] = f"未找到 caj2pdf：{home}"
        return res
    miss = missing_python_deps()
    if miss:
        res["reason"] = "缺 Python 依赖：" + ", ".join(miss)
        return res

    caj_abs = os.path.abspath(caj)
    pdf_abs = os.path.abspath(pdf)
    if not os.path.isfile(caj_abs):
        res["reason"] = "CAJ 文件不存在"
        return res

    old_cwd = os.getcwd()
    tmp = tempfile.mkdtemp(prefix="caj2pdf-")
    fmt = "?"
    # 产物一律先落在目的地同目录的临时名，只有 ok=True 才 os.replace 进 pdf_abs。
    # 上游 convert() 是边写边产出：若目的地直接用最终路径，失败/0 页时半截 PDF
    # 就永久留在 raw/pdf/Manual Download 里（违 R2），下一轮 find_existing_by_title
    # 会把它当"库里已有真 PDF"永久 skip，连重下机会都没有。
    out_dir = os.path.dirname(pdf_abs) or "."
    os.makedirs(out_dir, exist_ok=True)
    fd, tmp_pdf = tempfile.mkstemp(prefix=".caj2pdf-", suffix=".pdf", dir=out_dir)
    os.close(fd)
    fmt = "?"           # 先绑定：CAJParser() 构造失败时 except 分支要用它拼原因；
                        # 原来此时 fmt 尚未赋值 → except 里再抛 NameError，把真实异常盖掉
    path_added = False
    try:
        os.chdir(home)                      # import 期要能看见 ./lib/bin/*.dll
        # 光 chdir 不够：import 走 sys.path，不看 cwd。上游是命令行工具（脚本目录
        # 自动在 path 上），我们当库用就得自己加。
        if home not in sys.path:
            sys.path.insert(0, home)
            path_added = True
        for m in ("cajparser", "utils", "pdfwutils", "HNParsePage", "jbigdec", "jbig2dec"):
            sys.modules.pop(m, None)        # 上一次的模块状态不许串味
        import cajparser as CP              # noqa: WPS433
        res["engine"] = install_clean_shim(CP)
        os.chdir(tmp)                       # 转换期把临时文件关进临时目录
        try:
            parser = CP.CAJParser(caj_abs)
            fmt = getattr(parser, "format", "") or "?"
            res["caj_format"] = fmt
            if fmt in ("?", ""):
                res["reason"] = "Unknown file type.（caj2pdf 不认识这个文件）"
                return res
            parser.convert(tmp_pdf)
        except SystemExit as e:             # 上游用 SystemExit 报"不支持/外部命令失败"
            res["reason"] = f"caj2pdf({fmt})：{str(e)[:200]}"
            return res
        except KeyboardInterrupt:
            raise                   # Ctrl-C 不是"这篇转换失败"，不许咽进 res["reason"] 继续跑下一篇
        except BaseException as e:          # noqa: BLE001
            res["reason"] = f"caj2pdf({fmt})：{type(e).__name__}: {str(e)[:200]}"
            return res
        if not os.path.isfile(tmp_pdf):
            res["reason"] = f"caj2pdf({fmt})：未产出 PDF"
            return res

        # 产出复算：必须是有页面的真 PDF；顺手看有没有文字层（扫描件式 CAJ 提不出正文）
        import fitz
        doc = fitz.open(tmp_pdf)
        try:
            res["pages"] = doc.page_count
            head = "".join((doc[i].get_text() or "") for i in range(min(2, doc.page_count)))
        finally:
            doc.close()
        res["bytes"] = os.path.getsize(tmp_pdf)
        if res["pages"] <= 0:
            res["reason"] = f"caj2pdf({fmt})：产出的 PDF 没有页面"
            return res
        if res["bytes"] > 2000 * 1024 * 1024:
            res["reason"] = f"caj2pdf({fmt})：产出物异常大（{res['bytes']} B），判为转换失败"
            return res
        with open(tmp_pdf, "rb") as _fh:
            if not _fh.read(1024).startswith(b"%PDF"):
                res["reason"] = f"caj2pdf({fmt})：产出物没有 PDF 魔数"
                return res
        os.replace(tmp_pdf, pdf_abs)        # 到这一步目的地才允许出现文件
        res["ok"] = True
        res["has_text_layer"] = bool(head.strip())
        if not res["has_text_layer"]:
            res["note"] = "产出的 PDF 前两页没有可提取文字（扫描件式 CAJ，提取链收益有限）"
        return res
    finally:
        os.chdir(old_cwd)
        # path 用完还得还回去：caj2pdf 顶层有 utils.py 这类通用名，长期挂在
        # sys.path[0] 会遮蔽同进程后续的同名 import（模块本身已加载，移除不影响它）。
        if path_added:
            try:
                sys.path.remove(home)
            except ValueError:
                pass
        shutil.rmtree(tmp, ignore_errors=True)
        if os.path.exists(tmp_pdf):          # 失败路径：临时产物绝不留下
            try:
                os.unlink(tmp_pdf)
            except OSError:
                pass
        for junk in ("pdf.tmp", "pdf_toc.pdf", "tmp.pdf"):
            p = os.path.join(home, junk)
            if os.path.exists(p):
                try:
                    os.remove(p)
                except OSError:
                    pass


def convert_dir(src_dir: str, *, out_dir: str = "", keep_source: bool = True,
                limit: int = 0, quiet: bool = False) -> list[dict[str, Any]]:
    """批量转换目录里的 *.caj/*.kdh。转换成功后默认保留原 CAJ（--no-keep 才删）。"""
    if not os.path.isdir(src_dir):
        return [{"ok": False, "caj": src_dir, "reason": "目录不存在"}]
    files = sorted(f for f in os.listdir(src_dir) if f.lower().endswith((".caj", ".kdh")))
    if limit:
        files = files[:limit]
    rows: list[dict[str, Any]] = []
    for i, name in enumerate(files, 1):
        src = os.path.join(src_dir, name)
        dst = os.path.join(out_dir or os.path.dirname(src),
                           os.path.splitext(name)[0] + ".pdf")
        r = convert_one(src, dst)
        r["index"] = f"{i}/{len(files)}"
        if r["ok"] and not keep_source:
            try:
                os.remove(src)
            except OSError:
                pass
        if not quiet:
            print(f"[{i}/{len(files)}] {'✅' if r['ok'] else '❌'} {name}"
                  + (f" → {r['pages']} 页" if r["ok"] else f" — {r['reason'] or '?'}"))
        rows.append(r)
    return rows


# ---------------------------------------------------------------------------
# 自检（不需要真实 CAJ，也不联网）
# ---------------------------------------------------------------------------
def selftest() -> int:
    print("=== caj_to_pdf --selftest ===")
    ok = fail = env_fail = 0

    def chk(name: str, cond: bool, extra: str = "", env: bool = False) -> None:
        nonlocal ok, fail, env_fail
        if cond:
            ok += 1
            print(f"  [OK]   {name}")
        else:
            fail += 1
            if env:
                env_fail += 1
            print(f"  [FAIL] {name} {extra}")

    av = available()
    chk(f"能定位 caj2pdf 目录：{av['home']}", av["home_ok"], av["reason"], env=True)
    chk("Python 依赖齐备", not av["missing_python"], str(av["missing_python"]), env=True)
    chk("有 PyMuPDF 或真 mutool", av["fitz"] or av["real_mutool"], av["reason"])
    chk("ready 与三条判据一致",
        av["ready"] == (av["home_ok"] and not av["missing_python"]
                        and (av["fitz"] or av["real_mutool"])),
        json.dumps(av, ensure_ascii=False))

    tmp = tempfile.mkdtemp(prefix="caj-selftest-")
    try:
        junk = os.path.join(tmp, "junk.caj")
        with open(junk, "wb") as f:
            f.write(b"definitely not a caj file\n" * 40)
        r = convert_one(junk, os.path.join(tmp, "junk.pdf"))
        chk("垃圾输入判为失败", not r["ok"], str(r))
        chk("垃圾输入给出原因", bool(r["reason"]), str(r))
        chk("垃圾输入不产出 PDF", not os.path.exists(os.path.join(tmp, "junk.pdf")))

        import fitz
        src = os.path.join(tmp, "a.pdf")
        d = fitz.open()
        pg = d.new_page()
        pg.insert_text((72, 72), "hello caj_to_pdf")
        d.save(src)
        d.close()
        dst = os.path.join(tmp, "b.pdf")
        engine = _mutool_clean(src, dst)
        chk(f"mutool 替身可重排 PDF（{engine}）", os.path.isfile(dst))
        dd = fitz.open(dst)
        chk("重排后仍能读到文字层", "hello" in (dd[0].get_text() or ""))
        dd.close()

        if av["home_ok"] and not av["missing_python"]:
            import cajparser as CP          # noqa: WPS433
            install_clean_shim(CP)
            chk("check_output 已被替换", getattr(CP.check_output, "__name__", "") == "shim")
            try:
                CP.check_output(["something", "else"])
                chk("预期外调用被挡下", False, "没有抛 ShimError")
            except ShimError:
                chk("预期外调用被挡下", True)
        else:
            print("  [skip] 真实转换器未就绪，跳过 cajparser shim 自检。"
                  + (av["reason"] or "缺 caj2pdf 或 Python 依赖")
                  + "（可选层：按上方 reason 补齐后重跑 --selftest）")

        chk("临时文件没有落在转换器目录",
            all(not os.path.exists(os.path.join(av["home"], j))
                for j in ("pdf.tmp", "pdf_toc.pdf", "tmp.pdf")))

        # 回归（R2 泄漏）：上游 convert() 边写边产出，失败时目的地绝不能出现文件。
        # 用替身转换器精确复现两条路径：① 写了半截再 SystemExit；② 产出合法但 0 页。
        stub = os.path.join(tmp, "stubhome")
        os.makedirs(stub, exist_ok=True)
        with open(os.path.join(stub, "cajparser.py"), "w", encoding="utf-8") as f:
            f.write(
                "import os\n"
                "check_output = None\n"
                "class CAJParser:\n"
                "    format = 'HN'\n"
                "    def __init__(self, path):\n"
                "        pass\n"
                "    def convert(self, out):\n"
                "        if os.environ.get('CAJ_SELFTEST_STUB') == 'zeropage':\n"
                "            import fitz\n"
                "            d = fitz.open(); d.save(out); d.close()\n"
                "        else:\n"
                "            open(out, 'wb').write(b'%PDF-1.4\\ntruncated\\n')\n"
                "            raise SystemExit('selftest: 转换中断')\n")
        saved_path, saved_env = list(sys.path), os.environ.get("CAJ2PDF_HOME")
        os.environ["CAJ2PDF_HOME"] = stub
        try:
            for mode, name in (("partial", "上游中途失败时目的地不留文件"),
                               ("zeropage", "0 页产出判失败且不留文件")):
                os.environ["CAJ_SELFTEST_STUB"] = mode
                leak = os.path.join(tmp, f"leak-{mode}.pdf")
                r2 = convert_one(junk, leak)
                chk(name, (not r2["ok"]) and (not os.path.exists(leak)), str(r2))
                chk(f"{name}·有原因可查", bool(r2["reason"]), str(r2))
        finally:
            os.environ.pop("CAJ_SELFTEST_STUB", None)
            sys.path[:] = saved_path
            for m in ("cajparser", "utils", "pdfwutils",
                      "HNParsePage", "jbigdec", "jbig2dec"):
                sys.modules.pop(m, None)
            if saved_env is None:
                os.environ.pop("CAJ2PDF_HOME", None)
            else:
                os.environ["CAJ2PDF_HOME"] = saved_env
    finally:
        os.chdir(VAULT)
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n=== {ok}/{ok + fail} 通过 ===")
    # 退出码分工（Task 10 fix 轮）：0 全过；3 = 失败子项全部为可选环境判据
    # （caj2pdf 克隆件/其 Python 依赖未装齐，环境无关子项全过）——供 kb_toolcheck 精确豁免；
    # 2 = 存在环境无关失败（数据安全回归等）或装齐环境仍失败——真失败，不得豁免。
    if not fail:
        return 0
    if fail == env_fail and not av["ready"]:
        print("=== 退出码 3：仅可选环境未就绪（无环境无关失败），按可选层豁免 ===")
        return 3
    return 2


def main(argv: Optional[list[str]] = None) -> int:
    ap = argparse.ArgumentParser(
        description="CAJ/KDH → PDF 转换（知网专用；只有真 PDF 能进知识库提取链）")
    ap.add_argument("input", nargs="?", default="", help="单个 CAJ 文件")
    ap.add_argument("-o", "--output", default="", help="输出 PDF（默认同名同目录）")
    ap.add_argument("--batch", default="", help="批量转换该目录下所有 *.caj")
    ap.add_argument("--out-dir", default="", help="批量输出目录（默认原地）")
    ap.add_argument("--no-keep", action="store_true", help="转换成功后删除原 CAJ")
    ap.add_argument("--limit", type=int, default=0, help="批量最多处理多少个")
    ap.add_argument("--json", action="store_true", help="打印机器可读结果")
    ap.add_argument("--available", action="store_true", help="只做体检并退出")
    ap.add_argument("--selftest", action="store_true", help="自检（不需要真实 CAJ）")
    args = ap.parse_args(argv)

    if args.selftest:
        return selftest()
    if args.available:
        av = available()
        if args.json:
            print(json.dumps(av, ensure_ascii=False, indent=1))
        else:
            print(f"home           = {av['home']}")
            print(f"ready          = {av['ready']}")
            print(f"missing_python = {av['missing_python']}")
            print(f"fitz           = {av['fitz']}   real_mutool = {av['real_mutool']}")
            print(f"reason         = {av['reason'] or '—'}")
        return 0 if av["ready"] else 2
    if args.batch:
        rows = convert_dir(args.batch, out_dir=args.out_dir,
                           keep_source=not args.no_keep, limit=args.limit)
        if args.json:
            print(json.dumps(rows, ensure_ascii=False, indent=1))
        if not rows:
            print("[完成] 目录里没有 *.caj/*.kdh")
            return 0
        # 退出码分工（与 lit_* 家族一致，别让调用方把"几篇转失败"当成"环境坏了"）：
        #   0 全部成功 / 3 部分成功（可逐篇重试）/ 4 全部失败 / 2 环境与用法问题
        done = sum(1 for r in rows if r.get("ok"))
        if done == len(rows):
            return 0
        print(f"[批量] 成功 {done}/{len(rows)}；失败原因见上方逐篇 reason。")
        return 3 if done else 4
    if not args.input:
        ap.print_help()
        return 2
    out = args.output or (os.path.splitext(args.input)[0] + ".pdf")
    r = convert_one(args.input, out)
    if args.json:
        print(json.dumps(r, ensure_ascii=False, indent=1))
    elif r["ok"]:
        print(f"✅ {out}（{r['pages']} 页，{r['bytes']} B，文字层={r['has_text_layer']}）")
    else:
        print(f"❌ {r['reason'] or '转换失败'}")
    return 0 if r["ok"] else 2


if __name__ == "__main__":
    raise SystemExit(main())
